python3 - <<'EOF'
p='src/server/jobs/search-reindex-job.ts'
s=open(p).read()
start=s.index('/**\n * Walks one tenant')
head=s[:start]
body='''/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Only live content is indexed: archived projects, archived issues and deleted
 * comments are skipped. Every list is walked to the last page, so a tenant with
 * more rows than one page still gets fully indexed.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
      });

      for (const project of projects.items) {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
      });

      for (const issue of issues.items) {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          continue;
        }

        await reindexLiveComments(orgId, issue.id, result);
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);
  });
}

/**
 * Indexes every live comment on one issue, replies included. Pages through the
 * whole issue so long discussions are not cut short.
 */
async function reindexLiveComments(
  orgId: OrgId,
  issueId: IssueId,
  result: JobResult,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: PAGE_SIZE,
      cursor,
    });

    for (const comment of page.items) {
      try {
        await indexComment(orgId, comment);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index comment", {
          commentId: comment.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    cursor = page.nextCursor;
  } while (cursor !== null);
}
'''
head=head.replace('import type { OrgId } from "@/types/common";','import type { IssueId, OrgId } from "@/types/common";')
open(p,'w').write(head+body)
EOF
