          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
      });

      for (const issue of issues.items) {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          continue;
        }

        await reindexLiveComments(orgId, issue.id, result);
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);
  });
}

/**
 * Indexes every live comment on one issue, replies included. Pages through the
 * whole issue so long discussions are not cut short.
 */
async function reindexLiveComments(
  orgId: OrgId,
  issueId: IssueId,
  result: JobResult,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: PAGE_SIZE,
      cursor,
    });

    for (const comment of page.items) {
      try {
        await indexComment(orgId, comment);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index comment", {
          commentId: comment.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    cursor = page.nextCursor;
  } while (cursor !== null);
}
